function save(){try{localStorage.setItem(saveKey,JSON.stringify({state,tiles,seen,entities}));notify('CAMPAIGN SAVED');}catch(e){notify('Save unavailable on this browser.')}}function load(){try{let o=JSON.parse(localStorage.getItem(saveKey));if(o?.state&&o.tiles){state=o.state;tiles=o.tiles;W=tiles[0].length;H=tiles.length;state.collapseLeft??=900;state.warned??=[];seen=o.seen;entities=o.entities||[];state.dead=!!(state.dead||state.collapsed||state.hp<=0);return true}}catch(e){}return false}
