function trainBranch(n){let ranks=state.branches??={};let rank=ranks[n]||0;if(state.skillPoints<1||rank>=3||!state.specialization)return;let allowed={Vanguard:['Fortitude','Bulwark'],Arcanist:['Reservoir','Channeling'],Reaver:['Precision','Ferocity']}[state.specialization]||[];if(!allowed.includes(n)||(n===allowed[1]&&!(ranks[allowed[0]]>=2)))return;state.skillPoints--;ranks[n]=rank+1;if(n==='Fortitude'){state.maxHp+=10;state.hp+=10}else if(n==='Bulwark')state.armor+=2;else if(n==='Reservoir'){state.maxMp+=8;state.mp+=8}else if(n==='Channeling')state.spellBonus=(state.spellBonus||0)+5;else state.power+=n==='Ferocity'?3:2;save();render();openTab('skills')}function branchUI(){let a={Vanguard:['Fortitude','Bulwark'],Arcanist:['Reservoir','Channeling'],Reaver:['Precision','Ferocity']}[state.specialization];if(!a)return '';return '<div class="panel-title">CLASS SKILL TREE</div>'+a.map((n,i)=>'<button class="widebtn" data-branch="'+n+'" '+((i&&!(state.branches?.[a[0]]>=2))||(state.branches?.[n]||0)>=3?'disabled':'')+'>'+n+' • '+(state.branches?.[n]||0)+'/3 • 1 SP</button>').join('')}function chooseClass(n){if(state.specialization)return;state.specialization=n;if(n==='Vanguard'){state.maxHp+=15;state.hp+=15;state.armor+=2}else if(n==='Arcanist'){state.maxMp+=20;state.mp+=20}else state.power+=4;save();render();openTab('skills')}function openTab(t){tab=t;$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));let c=$('#tabContent');if(t==='journal'){c.innerHTML='<div class="panel-title">DUNGEON FEED <span class="muted">LIVE</span></div><div id="feed" class="feed"></div>';renderFeed()}else if(t==='map'){c.innerHTML='<div class="panel-title">CARTOGRAPHER’S MAP</div><p class="feed-line">The map reveals itself as you explore. Red marks living threats; white marks fallen enemies; gold marks your position and the exit.</p><div class="feed-line">Explored tiles: '+seen.flat().filter(Boolean).length+' / '+(W*H)+'</div>'}else if(t==='inventory'){c.innerHTML='<div class="panel-title">CRAWLER INVENTORY</div><div class="equipment-strip">⚔ Weapon • ⬟ Armor</div><div class="item-list inventory-grid">'+state.inventory.map(i=>`<div class="item-row"><span class="ico">${i.icon}</span><div><b>${i.name} ×${i.qty}</b><small>${i.desc}</small></div>${(['tonic','torch','shard'].includes(i.id)||i.id.startsWith('box-')||i.slot)?`<button class="smallbtn" data-use="${i.id}">${i.slot?(state.equipment?.[i.slot]===i.id?'EQUIPPED':'EQUIP'):i.id.startsWith('box-')?'OPEN':'USE'}</button>`:''}</div>`).join('')+'</div><button class="widebtn" id="addItem">＋ ADD CUSTOM ITEM</button>'}else if(t==='skills'){c.innerHTML=`<div class="panel-title">ABILITIES & TRAINING</div><div class="item-list"><div class="item-row"><span class="ico">⚔</span><div><b>Weapon mastery</b><small>Increase base strike damage. Current power: ${state.power}</small></div><button class="smallbtn" data-up="power">TRAIN • 1 SP</button></div><div class="item-row"><span class="ico">⬟</span><div><b>Iron constitution</b><small>Increase maximum health and armor.</small></div><button class="smallbtn" data-up="armor">TRAIN • 1 SP</button></div><div class="item-row"><span class="ico">✧</span><div><b>Arc Pulse</b><small>Area spell. Costs 10 MP; damages nearby enemies.</small><button class="smallbtn" data-action="spell">CAST</button></div></div></div><p>Unspent skill points: <b>${state.skillPoints}</b></p><div class="panel-title">SPECIALIZATION</div><p>${state.specialization||'Choose a permanent path'}</p>${branchUI()}${state.specialization?'': '<button class="widebtn" data-class="Vanguard">VANGUARD • +15 HP, +2 armor</button><button class="widebtn" data-class="Arcanist">ARCANIST • +20 MP</button><button class="widebtn" data-class="Reaver">REAVER • +4 power</button>'}`}else if(t==='party'){c.innerHTML='<div class="panel-title">PRIVATE CRAWLER PARTY</div><p>Connect to a hosted Dungeon Crawler relay to create an invite-only room. This alpha synchronizes party presence and positions; combat and dungeon state are not yet authoritative/shared.</p><div class="item-list"><label>SERVER WSS URL<input id="netEndpoint" class="modal-input" placeholder="wss://your-relay-host.example" value="'+safeAttr(localStorage.getItem('dck-net-url')||'')+'"></label><label>CRAWLER NAME<input id="netName" class="modal-input" maxlength="16" value="'+safeAttr(localStorage.getItem('dck-net-name')||'Crawler')+'"></label><div class="item-row"><button class="smallbtn" id="netCreate">CREATE PRIVATE ROOM</button><button class="smallbtn" id="netJoin">JOIN WITH CODE</button><button class="smallbtn" id="netLeave">LEAVE</button></div><div class="item-row"><span class="ico">♙</span><div><b id="netStatus">'+(window.DCKNet?.connected?'CONNECTED':'SOLO MODE')+'</b><small id="netRoom">'+(window.DCKNet?.roomCode?'ROOM '+window.DCKNet.roomCode:'No active room')+'</small></div><span class="achievement">ALPHA</span></div><div id="netRoster" class="feed-line">Remote crawlers: '+Object.keys(netPlayers).length+'</div></div><p>Use a secure WSS address for public hosting. Room codes are private invite codes, not user accounts or strong authentication.</p>'}}
function showModal(html){$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden')}function closeModal(){if(bossFight&&!state.dead)return;$('#modal').classList.add('hidden')}
function bind(){let field=document.createElement('div');field.className='field-map';field.innerHTML='<canvas width="240" height="180" id="fieldMini"></canvas>';$('.canvas-wrap').appendChild(field);const joy=$('#joystick'),knob=$('#joyKnob');if(joy&&knob){let pointer=null;const update=e=>{let b=joy.getBoundingClientRect(),x=e.clientX-b.left-b.width/2,y=e.clientY-b.top-b.height/2,d=Math.hypot(x,y),m=Math.min(1,36/Math.max(1,d));knob.style.transform=`translate(${x*m}px,${y*m}px)`;joyX=d>12?x/d:0;joyY=d>12?y/d:0};joy.addEventListener('pointerdown',e=>{if(pointer!==null)return;pointer=e.pointerId;joy.setPointerCapture(pointer);update(e);joyClock=0});joy.addEventListener('pointermove',e=>{if(e.pointerId===pointer)update(e)});const stop=e=>{if(e.pointerId!==pointer)return;pointer=null;joyX=joyY=0;knob.style.transform=''};for(const ev of ['pointerup','pointercancel','lostpointercapture'])joy.addEventListener(ev,stop)}document.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(k===' '||k==='j')attack();if(k==='shift')dodge();if(k==='e')spell();if(k==='f')loot();if(k==='q')jump();if(k==='w'||k==='arrowup')move(0,-1);if(k==='s'||k==='arrowdown')move(0,1);if(k==='a'||k==='arrowleft')move(-1,0);if(k==='d'||k==='arrowright')move(1,0);});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);$$('[data-move]').forEach(b=>{let fn=()=>{let d=b.dataset.move;move(d==='left'?-1:d==='right'?1:0,d==='up'?-1:d==='down'?1:0)};b.addEventListener('pointerdown',e=>{e.preventDefault();fn();touchMove=setInterval(fn,150)});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>clearInterval(touchMove)))});$$('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));$$('[data-tab]').forEach(b=>b.addEventListener('click',()=>openTab(b.dataset.tab)));$('#tabContent').addEventListener('click',e=>{let u=e.target.closest('[data-use]');if(u)useItem(u.dataset.use);let up=e.target.closest('[data-up]');if(up&&state.skillPoints>0){state.skillPoints--;if(up.dataset.up==='power')state.power+=2;else{state.maxHp+=15;state.armor++}feed('You train your '+up.dataset.up+'.');render();openTab('skills')}if(e.target.id==='addItem')addItem();let a=e.target.closest('[data-action]');if(a)action(a.dataset.action);if(e.target.id==='netCreate'||e.target.id==='netJoin'){const endpoint=$('#netEndpoint')?.value.trim(),name=($('#netName')?.value.trim()||'Crawler').slice(0,16);if(!endpoint){notify('Enter your hosted WSS server URL first.');return}localStorage.setItem('dck-net-url',endpoint);localStorage.setItem('dck-net-name',name);const btn=e.target;btn.disabled=true;window.DCKNet.connect(endpoint,name).then(()=>e.target.id==='netCreate'?window.DCKNet.createRoom():window.DCKNet.joinRoom(prompt('Enter your 6-character party code:')||'')).then(()=>{notify('PARTY CONNECTED');openTab('party')}).catch(err=>notify('CO-OP: '+err.message)).finally(()=>{btn.disabled=false})}if(e.target.id==='netLeave'){window.DCKNet?.leave();netPlayers={};openTab('party')}});$('#quickItems').addEventListener('click',e=>{let b=e.target.closest('[data-item]');if(b)useItem(b.dataset.item)});$('#saveBtn').onclick=save;$('#soundBtn').onclick=()=>{sound=!sound;$('#soundBtn').textContent=sound?'♫':'♩';notify(sound?'AUDIO ON':'AUDIO OFF')};$('#newRun').onclick=()=>{if(confirm('Abandon this run and start a new crawler?')){state=fresh();generate();render();save()}};$('#modalClose').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});window.addEventListener('beforeunload',save);}
function sanctuaryMenu(q){showModal('<h2>SANCTUARY</h2><p>Protected quarters • Gold: '+state.gold+'</p><button class="widebtn" id="restSafe">'+(q.rested?'BED — USED':'REST AT BED')+'</button><button class="widebtn" id="buySafe">MERCHANT: TONIC — 15 GOLD</button><button class="widebtn" id="stashSafe">'+(q.cache?'STORAGE — EMPTY':'OPEN SUPPLY CHEST')+'</button><button class="widebtn" id="leaveSafe">RETURN</button>');$('#restSafe').onclick=()=>{if(!q.rested){q.rested=true;state.hp=state.maxHp;state.mp=state.maxMp;unlock('Safe harbor');render()}sanctuaryMenu(q)};$('#buySafe').onclick=()=>{if(state.gold>=15){state.gold-=15;giveItem('tonic',1);render()}sanctuaryMenu(q)};$('#stashSafe').onclick=()=>{if(!q.cache){q.cache=true;awardBox('Bronze');render()}sanctuaryMenu(q)};$('#leaveSafe').onclick=closeModal}function giveItem(id,n){let i=state.inventory.find(v=>v.id===id);if(i)i.qty+=n;else{let names={tonic:'Health tonic',torch:'Torch',shard:'Mana shard'};state.inventory.push({id,name:names[id]||id,icon:'✦',qty:n,desc:'Dungeon supply'})}}function loot(){if(bossFight)return;let sanctuary=sanctuaryAt(state.x,state.y);if(sanctuary){sanctuaryMenu(sanctuary);return}if(state.npc&&!state.npc.met&&Math.hypot(state.x-state.npc.x,state.y-state.npc.y)<=1.7){state.npc.met=true;state.gold+=15;feed('A wandering crawler shares 15 gold and warns of the guardian.');unlock('Not alone');render();return}let e=entities.find(e=>!e.looted&&Math.hypot(e.x-state.x,e.y-state.y)<=1.7&&((e.type==='enemy'&&!e.alive)||(e.type==='loot'&&e.alive)));if(!e){notify('No remains or cache nearby.');return}e.looted=true;if(e.type==='loot')e.alive=false;let gold=5+Math.floor(Math.random()*10);state.gold+=gold;let id=Math.random()<.5?'tonic':'torch';let item=state.inventory.find(i=>i.id===id);if(item)item.qty++;feed('Loot recovered: '+gold+' gold and '+id+'.');unlock('Scavenger');state.loots=(state.loots||0)+1;if(state.loots===3)ridiculous('Personal Space Is for the Living');if(state.loots===15)ridiculous('Estate Sale Enthusiast','Silver');render();if(tab==='inventory')openTab(tab)}function action(a){if(a==='loot')loot();if(a==='attack')attack();if(a==='dodge')dodge();if(a==='jump')jump();if(a==='spell')spell()}
function updatePartyRoster(){const el=$('#netRoster');if(el)el.textContent='Party members connected: '+(window.DCKNet?.inRoom?Object.keys(netPlayers).length+1:0)+' / 4'}
window.addEventListener('dcknet',e=>{const d=e.detail||{};if(d.type==='players'){netPlayers=d.players||{};render();updatePartyRoster()}else if(d.type==='player_state'){netPlayers[d.id]=d.player;render();updatePartyRoster()}else if(d.type==='player_left'){delete netPlayers[d.id];render();updatePartyRoster()}else if(d.type==='room'){notify('PRIVATE ROOM '+d.code);render()}else if(d.type==='status'){const el=$('#netStatus');if(el)el.textContent=d.text;const room=$('#netRoom');if(room)room.textContent=d.code?'ROOM '+d.code:'No active room';updatePartyRoster()}else if(d.type==='error'){notify('CO-OP: '+d.message)}});
function collapseTick(dt){if(state.dead)return;state.collapseLeft=Math.max(0,(state.collapseLeft??900)-dt);let n=Math.ceil(state.collapseLeft),el=$('#collapseClock');if(el){el.textContent='COLLAPSE '+Math.floor(n/60)+':'+String(n%60).padStart(2,'0');el.style.color=n<=60?'#ff7766':'#e6c47d'}for(let t of [300,60,10])if(n<=t&&!state.warned.includes(t)){state.warned.push(t);ai('Floor collapse in '+t+' seconds. Find the stairs, crawler.');notify('COLLAPSE WARNING: '+t+'s')}if(n===0){bossFight=null;state.collapsed=true;state.dead=true;state.hp=0;save();showModal('<h2>FLOOR COLLAPSED</h2><p>You failed to reach the stairs in time.</p><button class="widebtn" id="collapseRestart">NEW RUN</button>');$('#collapseRestart').onclick=()=>{state=fresh();generate();closeModal();save()}}}document.addEventListener('click',e=>{let b=e.target.closest('[data-class]');if(b)chooseClass(b.dataset.class);let t=e.target.closest('[data-branch]');if(t)trainBranch(t.dataset.branch)});function tick(ts){let elapsed=last?Math.max(0,(ts-last)/1000||0):0,dt=Math.min(.05,elapsed);last=ts;collapseTick(Math.min(elapsed,1));if(step){let p=Math.min(1,(ts-step.start)/STEP_MS);p=Math.max(0,p);visualX=step.x+(step.nx-step.x)*p;visualY=step.y+(step.ny-step.y)*p;if(p>=1){let done=step;finishStep(done.nx,done.ny);step=null;visualX=state.x;visualY=state.y}}else{visualX=state.x;visualY=state.y}if(!state.dead){if(!step){let x=joyX||((keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)),y=joyY||((keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0));if(x||y){if(Math.abs(x)>Math.abs(y))move(Math.sign(x),0);else move(0,Math.sign(y))}}enemyTick(dt);drawMini();drawFieldMap();attackCooldown=Math.max(0,attackCooldown-dt);particles.forEach(p=>p.t+=dt);particles=particles.filter(p=>p.t<.65);if(Math.random()<dt*.025){try{localStorage.setItem(saveKey,JSON.stringify({state,tiles,seen,entities}))}catch(e){}}netSyncClock+=dt;if(netSyncClock>.18&&window.DCKNet?.inRoom){netSyncClock=0;window.DCKNet.sendState({floor:state.floor,x:state.x,y:state.y,level:state.level,hp:state.hp,maxHp:state.maxHp,name:localStorage.getItem('dck-net-name')||'Crawler'});}}draw();if(!state.dead&&Math.floor(ts/200)!==Math.floor((ts-dt*1000)/200))render();requestAnimationFrame(tick)}
